CREATE TABLE `Book_Tab` (
  `BookTabID` int(11) NOT NULL AUTO_INCREMENT,
  `BookID` int(11) NOT NULL DEFAULT '0',
  `TabID` int(11) NOT NULL DEFAULT '0',
  `TabRankInBook` int(11) NOT NULL DEFAULT '0',
  `IsLive` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `DateModified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `DateAdded` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `IsArchived` tinyint(4) NOT NULL DEFAULT '0',
  `TabDescription` text,
  `TabDescriptionDetail` text,
  PRIMARY KEY (`BookTabID`),
  KEY `BookID` (`BookID`),
  KEY `TabID` (`TabID`),
  KEY `TabRankInBook` (`TabRankInBook`),
  KEY `IsArchived` (`IsArchived`)
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=latin1;
